// Bound to verified local catalog assets; hero selection and image bytes are untouched.
export function productSocialImage(product, provenance, origin, brand) {
  const base = new URL(origin);
  if (base.protocol !== 'https:' || base.username || base.password) throw new Error('Social images require the canonical HTTPS origin');
  const proof = provenance.products.find(row => row.key === product?.key);
  if (!proof || product.assetType !== 'real_product' || product.sourceLevel !== 'official_business_source'
      || product.img !== proof.image.path || product.name !== proof.name
      || product.sourceUrl !== proof.sourceUrl || product.orderUrl !== proof.orderUrl
      || !/^\/images\/products\/[a-zA-Z0-9_/-]+\.(?:jpe?g|png|webp)$/.test(product.img)
      || product.img.includes('..')) throw new Error('Social image must match a verified local catalog asset');
  const [width, height] = proof.image.dimensions;
  if (![width, height].every(value => Number.isInteger(value) && value > 0)
      || !['image/jpeg','image/png','image/webp'].includes(proof.image.type)
      || !/^[0-9a-f]{64}$/.test(proof.image.sha256)) throw new Error('Missing verified image metadata');
  return {url:new URL(product.img,base.origin).href,alt:`${brand} ${product.name}`,width,height,type:proof.image.type};
}

src/lib/sources.mjs.utf8Content:
export const sourceTypeLabels = Object.freeze({
  official: '공공·기관', business: '사업자', facility: '시설',
  education: '교육기관', professional: '전문자료', reference: '참고자료',
});

// The reviewed array is authoritative; only older pages without it use source.
// Never normalize, deduplicate, reorder, or silently drop a reviewed source.
export function pageSources(page) {
  const sources = page.sources == null ? (page.source ? [page.source] : []) : page.sources;
  if (!Array.isArray(sources)) throw new Error('Page sources must be an array');
  for (const source of sources) {
    let url;
    try { url = new URL(source?.url); } catch { throw new Error('Invalid source HTTPS URL'); }
    if (url.protocol !== 'https:' || !url.hostname || url.username || url.password ||
        source.url !== source.url.trim() || /[\u0000-\u0020\u007f\\]/.test(source.url)) {
      throw new Error('Source must be an HTTPS URL without credentials or control characters');
    }
    if (typeof source.name !== 'string' || !source.name.trim() ||
        !Object.hasOwn(sourceTypeLabels, source.type) ||
        typeof source.verifiedAt !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(source.verifiedAt)) {
      throw new Error('Source name, supported type, and verification date are required');
    }
  }
  return sources;
}

src/lib/visual.mjs.utf8Content:
/** An explicit reviewed slot takes priority over a legacy page-type fallback. */
export function detailIllustration(page, editorial) {
  if (page.assetSlot === 'REAL_PROOF' || page.assetSlot === 'NONE') return null;
  // This template has real catalog photography and one square editorial asset.
  // Other dedicated slots need a separately reviewed adapter, not a guessed crop.
  if (page.assetSlot) throw new Error(`No compatible detail asset for slot: ${page.assetSlot}`);
  if (['congrats_wreath', 'funeral_wreath'].includes(page.visualIntent)) return null;
  return page.pageType === 'business-opening' || page.visualIntent === 'event_wreath'
    ? editorial.openingWreath : null;
}

