const slugs=["bukbyeon-dong", "geolpo-dong", "unyang-dong", "janggi-dong", "gamjeong-dong", "sau-dong", "pungmu-dong", "masan-dong", "gurae-dong", "tongjin-eup", "gochon-eup", "yangchon-eup", "daegot-myeon", "wolgot-myeon", "haseong-myeon"];
